  ui_story_5059_50590103_76_dialog_content = "¿Inclus también hacer piruletas?? tiered and lollipops? Linden.",
  ui_story_5059_50590103_77_dialog_content = "Quiero darte uno, PlayerName...",
  ui_story_5059_50590103_78_dialog_content = "¿A mí? ¿Estás seguro?",
  ui_story_5059_50590103_79_dialog_content = "Sí... PlayerName es un buen chico.",
  ui_story_5059_50590103_80_dialog_content = "¡Gracias, lo apreciaré!",
  ui_story_5059_50590103_81_dialog_content = "Vamos a buscar a Lady Elma. Te ayudaré.",
  ui_story_5059_50590103_82_dialog_content = "Tonto PlayerName.",
  ui_story_5059_50590103_83_dialog_content = "Un chico malo que no le importa nada de mí.",
  ui_story_5059_50590103_84_dialog_content = "No puedo hacer eso, PlayerName. Kanna está en una edad en la que necesita amor y cuidado tierno.",
  ui_story_5059_50590103_85_dialog_content = "Estás empezando a decepcionarme, PlayerName...",
  ui_story_5059_50590103_86_dialog_content = "¡Lo siento, lo siento! Mis disculpas a todos.",
  ui_story_5059_50590103_87_dialog_content = "¡Dame otra oportunidad, por favor! ¡Esta vez tomaré la decisión correcta!",
  ui_story_5059_50590104_1_dialog_content = "¡No!",
  ui_story_5059_50590104_2_dialog_content = "Oye, ¿es ese Vice?",
  ui_story_5059_50590104_3_dialog_content = "Vamos a verlo.",
  ui_story_5059_50590104_4_dialog_content = "No dejaré que vendas cosas tan raras a los amigos de PlayerName.",
  ui_story_5059_50590104_5_dialog_content = "Pero señorita Vice, esta jovencita está muy interesada en mis ofertas.",
  ui_story_5059_50590104_6_dialog_content = "Mira, este es el nuevo producto del exclusivo pastelero de los prestigiosos nobles de Lumopolis.",
  ui_story_5059_50590104_7_dialog_content = "¡Esta última línea de postres surtidos al azar solo está disponible esta semana!",
  ui_story_5059_50590104_8_dialog_content = "¿Cómo logró ese extraño comerciante enganchar a Elma de nuevo?",
  ui_story_5059_50590104_9_dialog_content = "¿Quizás tiene la habilidad de atraer vendedores?",
  ui_story_5059_50590104_10_dialog_content = "Ella parece ser el tipo de persona que se deja convencer fácilmente para comprar cosas.",
  ui_story_5059_50590104_11_dialog_content = "Esta caja de postres aleatorios suena tentadora.",
  ui_story_5059_50590104_12_dialog_content = "Sabía que tienes buen gusto. Mira, Señorita Vice, ella está muy interesada.",
  ui_story_5059_50590104_13_dialog_content = "¡Sigue siendo un \"No!\" La engañaste con tu discurso.",
  ui_story_5059_50590104_14_dialog_content = "De ninguna manera. Los negocios siempre han sido sobre el valor justo y asegurarse de que todos obtengan lo que necesitan.",
  ui_story_5059_50590104_15_dialog_content = "¡Pero no con cajas sorpresa de postres! ¡Estás siendo irrespetuoso con la comida!",
  ui_story_5059_50590104_16_dialog_content = "Por ofrecer postre y la emoción de la lotería al mismo tiempo, deberías llamarme un genio del marketing, Señorita Vice.",
  ui_story_5059_50590104_17_dialog_content = "Permítame mostrarle otra serie de cajas sorpresa de postres, señora.",
  ui_story_5059_50590104_18_dialog_content = "No es una oferta limitada, pero incluye un plato secreto que solo alguien que lo pida descubrirá qué es.",
  ui_story_5059_50590104_19_dialog_content = "¿Qué, un postre secreto?",
  ui_story_5059_50590104_20_dialog_content = "Jomu!",
  ui_story_5059_50590104_21_dialog_content = "Oh, hola, ahí estás, jefe.",
  ui_story_5059_50590104_22_dialog_content = "¿Estás molestando a la gente con cosas raras otra vez?",
  ui_story_5059_50590104_23_dialog_content = "Estás equivocado, jefe. La dama y yo nos llevamos muy bien. No puedes llamarlo acoso.",
  ui_story_5059_50590104_24_dialog_content = "En realidad...",
  ui_story_5059_50590104_25_dialog_content = "Por supuesto. Puedes poner a prueba nuestra amistad de cualquier manera, en cualquier momento.",
  ui_story_5059_50590104_26_dialog_content = "Tengo exactamente lo que necesitas para eso. Si puedes pasar el Desafío de Rapport 4, creeré que no estabas acosando a Elma.",
  ui_story_5059_50590104_27_dialog_content = "Pero por otro lado, si la pifias... Tienes que darle todas las cajas sorpresa a ella como compensación.",
  ui_story_5059_50590104_28_dialog_content = "Bueno, aunque eso no suena justo...",
  ui_story_5059_50590104_29_dialog_content = "¡El premio definitivamente vale la pena! ¡Comencemos ahora!",
  ui_story_5059_50590104_30_dialog_content = "¿A Elma realmente le gusta mucho Tohru?",
  ui_story_5059_50590104_31_dialog_content = "Si",
  ui_story_5059_50590104_32_dialog_content = "¿Por qué empezar con una pregunta tan directa?",
  ui_story_5059_50590104_33_dialog_content = "Ejem... No es posible que me guste Tohru... Solo es que nos conocemos desde hace mucho tiempo, eso es todo.",
  ui_story_5059_50590104_34_dialog_content = "Simplemente me gusta entrenar con ella. ¡Supongo que está destinada a ser mi némesis!",
  ui_story_5059_50590104_35_dialog_content = "Entonces, ¿por qué elegiste esta respuesta?",
  ui_story_5059_50590104_36_dialog_content = "¿Qué? Oh, debo haberlo agarrado por accidente.",
  ui_story_5059_50590104_37_dialog_content = "¡Es tu culpa por no mostrarme cómo usarlo correctamente!",
  ui_story_5059_50590104_38_dialog_content = "Ese encubrimiento fue demasiado obvio, Elma...",
  ui_story_5059_50590104_39_dialog_content = "Oh... ¡Siguiente pregunta, ahora!",
  ui_story_5059_50590104_40_dialog_content = "No",
  ui_story_5059_50590104_41_dialog_content = "¿Por qué empezar con una pregunta tan directa?",
  ui_story_5059_50590104_42_dialog_content = "¡No es posible que me guste Tohru!",
  ui_story_5059_50590104_43_dialog_content = "Entonces, ¿por qué elegiste la otra respuesta?",
  ui_story_5059_50590104_44_dialog_content = "Oh... Bueno, ¡no quería darle una victoria fácil a un simple Caelestite!",
  ui_story_5059_50590104_45_dialog_content = "Entonces... ¿A Elma le gusta o no le gusta Tohru?",
  ui_story_5059_50590104_46_dialog_content = "¿No está claro como el día?",
  ui_story_5059_50590104_47_dialog_content = "Por supuesto ella...",
  ui_story_5059_50590104_48_dialog_content = "¡Alto! ¡Compraré las cajas!",
  ui_story_5059_50590104_49_dialog_content = "¿Qué se necesita para que Elma se una a una batalla dentro de la facción del Caos?",
  ui_story_5059_50590104_50_dialog_content = "Pastel de chocolate súper grande",
  ui_story_5059_50590104_51_dialog_content = "Entonces, ¿un pastel de chocolate súper grande no sería suficiente?",
  ui_story_5059_50590104_52_dialog_content = "Por supuesto que no. Es peligroso involucrarse en una pelea entre dos facciones.",
  ui_story_5059_50590104_53_dialog_content = "Por no mencionar que es solo un pastel súper grande... ¿Crees que nosotros, los dragones, no tenemos orgullo?",
  ui_story_5059_50590104_54_dialog_content = "¿Y si fuera uno aún más grande?",
  ui_story_5059_50590104_55_dialog_content = "Si fuera tan grande que no pudiera terminarlo incluso en forma de dragón, ¡lo consideraría!",
  ui_story_5059_50590104_56_dialog_content = "Todos los dulces que pueda comer",
  ui_story_5059_50590104_57_dialog_content = "Prefiero el tipo hecho por chefs del palacio.",
  ui_story_5059_50590104_58_dialog_content = "Los probé antes y aún recuerdo lo buenos que sabían.",
  ui_story_5059_50590104_59_dialog_content = "Te puedo prometer que los que están en mis cajas sorpresa están a la par con cualquier cosa que hayas probado.",
  ui_story_5059_50590104_60_dialog_content = "Para, Jomu. Te dije que dejaras el discurso de ventas.",
  ui_story_5059_50590104_61_dialog_content = "Mucho menos colarlo durante un juego como si fuera un anuncio.",
  ui_story_5059_50590104_62_dialog_content = "Bueno, en realidad, he estado aprendiendo a hacer postres.",
  ui_story_5059_50590104_63_dialog_content = "...",
  ui_story_5059_50590104_64_dialog_content = "¿Por qué te has callado de repente?!",
  ui_story_5059_50590104_65_dialog_content = "¿Has desafiado a Tohru para ver quién tiene la cola más larga?",
  ui_story_5059_50590104_66_dialog_content = "Si",
  ui_story_5059_50590104_67_dialog_content = "Vale, ¿a quién se le ocurrió esta pregunta?",
  ui_story_5059_50590104_68_dialog_content = "Tohru probablemente aún recuerda cosas triviales como esa...",
  ui_story_5059_50590104_69_dialog_content = "Bueno, la pregunta fue de hecho de Tohru.",
  ui_story_5059_50590104_70_dialog_content = "Debe verte como un amigo para tener en cuenta esos pequeños detalles.",
  ui_story_5059_50590104_71_dialog_content = "¿A qué te refieres? Estoy seguro de que es porque ella nunca podría olvidar los desafíos que ha tenido contra un poderoso dragón como yo!",
  ui_story_5059_50590104_72_dialog_content = "No",
  ui_story_5059_50590104_73_dialog_content = "¿Entonces eso también es un \"desafío\"?",
  ui_story_5059_50590104_74_dialog_content = "Sí. Hubo un período de tiempo en el que me gustaba desafiar a Tohru en todo tipo de cosas.",
  ui_story_5059_50590104_75_dialog_content = "Eso suena como si estuvieras intentando llamar su atención.",
  ui_story_5059_50590104_76_dialog_content = "Ustedes dos están unidos.",
  ui_story_5059_50590104_77_dialog_content = "¿Te gustaría pedir un pastel personalizado para simbolizar vuestra amistad entonces?",
  ui_story_5059_50590104_78_dialog_content = "¡No!",
  ui_story_5059_50590104_79_dialog_content = "No acertaste en todo, Jomu.",
  ui_story_5059_50590104_80_dialog_content = "Eres la mejor persona. Admito mi derrota, jefe.",
  ui_story_5059_50590104_81_dialog_content = "Me siento avergonzado por no haber investigado lo suficiente sobre mi cliente...",
  ui_story_5059_50590104_82_dialog_content = "Nunca subestimes el vínculo entre aquellos que han vivido aventuras y luchado juntos, Jomu.",
  ui_story_5059_50590104_83_dialog_content = "Eso no es algo que puedas obtener de la observación y los rumores.",
  ui_story_5059_50590104_84_dialog_content = "No pensé que supieras tanto sobre mí, PlayerName. ¿Hay algo en lo que te gustaría que te ayudara?",
  ui_story_5059_50590104_85_dialog_content = "Agradezco la oferta, pero creo que tú también tienes mucho en tu plato.",
  ui_story_5059_50590104_86_dialog_content = "Ustedes, mortales, seguro llevan una vida ocupada.",
  ui_story_5059_50590104_87_dialog_content = "No te preocupes, tenemos la capacidad de enfrentar lo que sucede en nuestro mundo.",
  ui_story_5059_50590104_88_dialog_content = "Derecha, Vice?",
  ui_story_5059_50590104_89_dialog_content = "Vice...? ¿A dónde fue?",
  ui_story_5059_50590104_90_dialog_content = "Espera, ¿qué es ese olor? Tan fuerte...",
  ui_story_5059_50590104_91_dialog_content = "¡PlayerName! ¡Elma!",
  ui_story_5059_50590104_92_dialog_content = "¡Hice un pastel...!",
  ui_story_5059_50590104_93_dialog_content = "¡Corre, Elma!",
  ui_story_5059_50590104_94_dialog_content = "¿Qué dijiste? ¡Espera!",
  ui_story_5059_50590104_95_dialog_content = "Escuché que te gustan los postres, Elma, así que hice un montón para ti.",
  ui_story_5059_50590104_96_dialog_content = "Puedes disfrutarlo desde la mañana hasta la tarde.",
  ui_story_5059_50590104_97_dialog_content = "No puedo creer que perdí contra Jomu...",
  ui_story_5059_50590104_98_dialog_content = "¡Cálmate, PlayerName!",
  ui_story_5059_50590104_99_dialog_content = "Si no lo haces, Jomu va a estafar a Elma para que compre todas las cajas.",
  ui_story_5059_50590104_100_dialog_content = "Por no mencionar que Elma no tiene mucho dinero, así que podríamos quedarnos con la cuenta después de que se vaya.",
  ui_story_5059_50590104_101_dialog_content = "¡¿Qué?!",
  ui_story_5059_50590104_102_dialog_content = "No puedo rendirme aún. ¡Déjame intentarlo de nuevo!",
  ui_story_5059_50590105_1_dialog_content = "Lucoa!",
  ui_story_5059_50590105_2_dialog_content = "Ahí estás, por fin.",
  ui_story_5059_50590105_3_dialog_content = "PlayerName! ¿Estás aquí para tomar té?",
  ui_story_5059_50590105_4_dialog_content = "Es de la colección privada de Liu y hecho por la Señora Sheol.",
  ui_story_5059_50590105_5_dialog_content = "¡Oh, gracias! ¿Sheol también está aquí?",
  ui_story_5059_50590105_6_dialog_content = "Naturalmente, una competente asistente reuniéndose con su jefe es una ocasión feliz que vale la pena celebrar.",
  ui_story_5059_50590105_7_dialog_content = "Sin mencionar que a Lucoa todavía se le debe una parte de su pago.",
  ui_story_5059_50590105_8_dialog_content = "Bueno, realmente puedo prescindir del pago. Solo lo veo como otra forma de vivir.",
  ui_story_5059_50590105_9_dialog_content = "Solo más rec 1 y the 100% en línea.",
  ui_story_5059_50590105_10_dialog_content = "Siento lo mismo acerca de los recuerdos, no es de extrañar que estemos totalmente sincronizados en el trabajo.",
  ui_story_5059_50590105_11_dialog_content = "En ese caso, no te importaría crear más recuerdos, ¿verdad?",
  ui_story_5059_50590105_12_dialog_content = "¿Qué tienes en mente, <lock_0, <<lock  sagas in lgbt, PlayerName",
  ui_story_5059_50590105_13_dialog_content = "¡Conse yea! ¡, ¡Conseguí!",
  ui_story_5059_50590105_14_dialog_content = "Shouta una vez confundió a Lucoa con un...",
  ui_story_5059_50590105_15_dialog_content = "Demonio",
  ui_story_5059_50590105_16_dialog_content = "¿Demonio?",
  ui_story_5059_50590105_17_dialog_content = "¿Es Lucoa un demonio?",
  ui_story_5059_50590105_18_dialog_content = "¿Cómo puede",
  ui_story_5059_50590105_19_dialog_content = "Pero Shouta es un niño terco que insistió en que yo era un demonio.",
  ui_story_5059_50590105_20_dialog_content = "A pesar de intentar demostrárselo muchas veces, aún no ha cambiado de opinión.",
  ui_story_5059_50590105_21_dialog_content = "Pero eso nunca afectó lo cerca que están ustedes dos, ¿verdad?",
  ui_story_5059_50590105_22_dialog_content = "Subterráneo",
  ui_story_5059_50590105_23_dialog_content = "¿Subterráneo?",
  ui_story_5059_50590105_24_dialog_content = "¿Quieres decir personas que vivían muy bajo tierra, verdad?",
  ui_story_5059_50590105_25_dialog_content = "Que yo sepa, no existe un lugar así.",
  ui_story_5059_50590105_26_dialog_content = "Bueno, estoy viendo un dragón en forma humanoide vivo y coleando ante mis ojos, así que...",
  ui_story_5059_50590105_27_dialog_content = "La Diosa de la Serpiente Alada, la verdadera forma de Lucoa, ¿gobierna sobre qué dominio?",
  ui_story_5059_50590105_28_dialog_content = "Civilización",
  ui_story_5059_50590105_29_dialog_content = "¿De verdad gobiernas sobre civilizaciones en tu mundo, Lucoa?",
  ui_story_5059_50590105_30_dialog_content = "in a le in  </span>Por supuesto, y también soy, muy poder MST in Spanish 2000 2. earmen.",
  ui_story_5059_50590105_31_dialog_content = "Mmm...",
  ui_story_5059_50590105_32_dialog_content = "Mmm...",
  ui_story_5059_50590105_33_dialog_content = "Oigan, ¿por qué todos me miran así?",
  ui_story_5059_50590105_34_dialog_content = "¡En serio!",
  ui_story_5059_50590105_35_dialog_content = "No dudo de la amplitud de conocimientos que posee Lucoa.",
  ui_story_5059_50590105_36_dialog_content = "Ha sido de gran ayuda para el Gremio.",
  ui_story_5059_50590105_37_dialog_content = "Supongo que Lucoa es mucho más capaz de lo que parece.",
  ui_story_5059_50590105_38_dialog_content = "¡Se asustará Sheol si me convierto en un dragón!",
  ui_story_5059_50590105_39_dialog_content = "Ganadería",
  ui_story_5059_50590105_40_dialog_content = "Suspiro...",
  ui_story_5059_50590105_41_dialog_content = "¿Por qué crees que tengo algo que ver con el ganado?",
  ui_story_5059_50590105_42_dialog_content = "Bueno, no estoy exactamente seguro de dónde saqué la idea de que cuidarías animales y plantas...",
  ui_story_5059_50590105_43_dialog_content = "¿Quizás por lo atento y protector que eres hacia Shouta?",
  ui_story_5059_50590105_44_dialog_content = "Ya veo. Supongo que puedo aceptar eso... ¡Apenas!",
  ui_story_5059_50590105_45_dialog_content = "Lucoa en realidad es de Shouta...",
  ui_story_5059_50590105_46_dialog_content = "Sirvienta",
  ui_story_5059_50590105_47_dialog_content = "¡¿Qué?!",
  ui_story_5059_50590105_48_dialog_content = "¡Ni siquiera llevo puesto un disfraz de sirvienta!",
  ui_story_5059_50590105_49_dialog_content = "Es cierto... Tohru está usando un traje de sirvienta.",
  ui_story_5059_50590105_50_dialog_content = "¿Elegiste esto porque te fascinan las sirvientas, PlayerName?",
  ui_story_5059_50590105_51_dialog_content = "¿Qué tal si te doy algunos disfraces de sirvienta para que se los des a las chicas que te gustan? O tal vez puedas probártelos tú mismo cuando estés solo.",
  ui_story_5059_50590105_52_dialog_content = "¡Por favor, córtalo!",
  ui_story_5059_50590105_53_dialog_content = "Familiar",
  ui_story_5059_50590105_54_dialog_content = "Teóricamente, los familiares son la mitad más débil, por lo que es imposible que un dragón sirva como familiar.",
  ui_story_5059_50590105_55_dialog_content = "¡Es simplemente cómo Shouta me trata!",
  ui_story_5059_50590105_56_dialog_content = "Shouta debe estar feliz de que Lucoa lo esté molestando... quiero decir, cuidando bien de él.",
  ui_story_5059_50590105_57_dialog_content = "Dado que Lucoa es tan empático, después de todo.",
  ui_story_5059_50590105_58_dialog_content = "Dicho esto, sigue siendo difícil averiguar lo que un chico de su edad está pensando.",
  ui_story_5059_50590105_59_dialog_content = "Déjame pensar, cuando mi hermano era pequeño...",
  ui_story_5059_50590105_60_dialog_content = "Oye, ¿ya se acabó el juego?",
  ui_story_5059_50590105_61_dialog_content = "Sí. Gronru dijo tres preguntas por juego.",
  ui_story_5059_50590105_62_dialog_content = "Pero no creo que puedas llegar lo suficientemente profundo de esa manera.",
  ui_story_5059_50590105_63_dialog_content = "¿No quieres saber más sobre mí, PlayerName?",
  ui_story_5059_50590105_64_dialog_content = "Bueno...",
  ui_story_5059_50590105_65_dialog_content = "PlayerName es el tipo de persona que no aguanta las bromas, Lucoa.",
  ui_story_5059_50590105_66_dialog_content = "Si sigues así, se lo llevará el viento.",
  ui_story_5059_50590105_67_dialog_content = "¡No lo haré!",
  ui_story_5059_50590105_68_dialog_content = "Bien entonces...",
  ui_story_5059_50590105_69_dialog_content = "¡Paremos justo aquí!",
  ui_story_5059_50590105_70_dialog_content = "Oh, ¿dónde fue Fafnir, alguien sabe?",
  ui_story_5059_50590105_71_dialog_content = "¿Te refieres al hombre con las gafas?",
  ui_story_5059_50590105_72_dialog_content = "Lo vi entrar en otra habitación.",
  ui_story_5059_50590105_73_dialog_content = "¿Por qué tienes prisa por encontrar Fafnir, PlayerName?",
  ui_story_5059_50590105_74_dialog_content = [[
No T, not a content farm.
2019]],
  ui_story_5059_50590105_75_dialog_content = "Oh, Dios.",
  ui_story_5059_50590105_76_dialog_content = "¡No! Ayúdame aquí, Sra. Sheol!",
  ui_story_5059_50590105_77_dialog_content = "PlayerName efectivamente pasó mucho tiempo con hombres, como Corax de Umbraton, el líder de Rediesel Wrench, Barton en Illumina.",
  ui_story_5059_50590105_78_dialog_content = "Jeje, no es de extrañar.",
  ui_story_5059_50590105_79_dialog_content = "¡Tengo que irme ahora!",
  ui_story_5059_50590105_80_dialog_content = "Veo que PlayerName todavía no sabe lo suficiente sobre mí!",
  ui_story_5059_50590105_81_dialog_content = "¿Sería necesario tener una conversación privada uno a uno con PlayerName para mejorar nuestra comprensión mutua?",
  ui_story_5059_50590105_82_dialog_content = "No, eso no será necesario, ¡muchas gracias!",
  ui_story_5059_50590105_83_dialog_content = "I just made a (laughs the endtail6 be. I'm 2015.",
  ui_story_5059_50590106_1_dialog_content = "Aquí estás, PlayerName, finalmente.",
  ui_story_5059_50590106_2_dialog_content = "¿Me estabas esperando? Te estaba buscando.",
  ui_story_5059_50590106_3_dialog_content = "Sí RET -,-",
  ui_story_5059_50590106_4_dialog_content = "¿Qué puede ser tan horrible como para ponerte tan nervioso?",
  ui_story_5059_50590106_5_dialog_content = "Pensé que mis habilidades para jugar videojuegos habían alcanzado su máximo después de practicar con Takiya.",
  ui_story_5059_50590106_6_dialog_content = "Pero para mi sorpresa, el rango más alto que pude alcanzar fue el segundo lugar en todos los juegos aquí.",
  ui_story_5059_50590106_7_dialog_content = "¿Quién es el abusón Gronru en primer lugar?",
  ui_story_5059_50590106_8_dialog_content = "(¿Bully Gronru? ¿No es ese Gronru?)",
  ui_story_5059_50590106_9_dialog_content = "(¿Cómo es que no la veo ahora? ¿A dónde fue?)",
  ui_story_5059_50590106_10_dialog_content = "¿Es ella la deidad encargada de los juegos en este mundo?",
  ui_story_5059_50590106_11_dialog_content = "Si eso es cierto, debo desafiarla.",
  ui_story_5059_50590106_12_dialog_content = "Bueno, sé exactamente quién es el abusón Gronru.",
  ui_story_5059_50590106_13_dialog_content = "¿Qué? ¿La verdadera forma de Bully Gronru?",
  ui_story_5059_50590106_14_dialog_content = "Dime. Incluso conceder deseos a cambio no está fuera de discusión.",
  ui_story_5059_50590106_15_dialog_content = "¿O preferirías aprender maleficios que corrompen y caen sobre otros?",
  ui_story_5059_50590106_16_dialog_content = "¡Alto! No me interesa eso en absoluto.",
  ui_story_5059_50590106_17_dialog_content = "De todos modos, juguemos este juego primero, luego te contaré sobre ella, ganes o pierdas.",
  ui_story_5059_50590106_18_dialog_content = "El nombre Tohru utilizado para establecer una identidad para ti fue...",
  ui_story_5059_50590106_19_dialog_content = "Behemoth",
  ui_story_5059_50590106_20_dialog_content = "¡Recuerdo que ella mencionó eso!",
  ui_story_5059_50590106_21_dialog_content = "Eso es porque tu forma de dragón se parece a un behemoth en las montañas, ¿verdad?",
  ui_story_5059_50590106_22_dialog_content = "Sí, también recuerdo que Tohru lo dijo.",
  ui_story_5059_50590106_23_dialog_content = "Por supuesto que recordarías las cosas aburridas.",
  ui_story_5059_50590106_24_dialog_content = "Deberías dedicar más tiempo a las historias épicas sobre mí.",
  ui_story_5059_50590106_25_dialog_content = "Por ejemplo, ¿cuántos juegos perdiste?",
  ui_story_5059_50590106_26_dialog_content = "Veo que no te preocupa en absoluto tu seguridad personal.",
  ui_story_5059_50590106_27_dialog_content = "Triturador",
  ui_story_5059_50590106_28_dialog_content = "¿Qué tipo de nombre ridículo es ese...",
  ui_story_5059_50590106_29_dialog_content = "Creo que está hecho para ser incorrecto a propósito.",
  ui_story_5059_50590106_30_dialog_content = "¡Pero eso sí suena como un alias para un jugador empedernido!",
  ui_story_5059_50590106_31_dialog_content = "Debo admitir que el nombre te queda bien.",
  ui_story_5059_50590106_32_dialog_content = "Veo que no te preocupa en absoluto tu seguridad personal.",
  ui_story_5059_50590106_33_dialog_content = "Para Fafnir, Takiya es...",
  ui_story_5059_50590106_34_dialog_content = "Un compañero de cuarto y comida gratis",
  ui_story_5059_50590106_35_dialog_content = "Puedes decirlo así, pero también \"Guardián de los objetos valiosos\".",
  ui_story_5059_50590106_36_dialog_content = "Entiendo, él es un hogareño a quien también le gusta jugar, ¿verdad?",
  ui_story_5059_50590106_37_dialog_content = "¡Estás en el punto hoy, Raphael!",
  ui_story_5059_50590106_38_dialog_content = "Je-je.",
  ui_story_5059_50590106_39_dialog_content = "Mmm...",
  ui_story_5059_50590106_40_dialog_content = "Una necesidad para obtener artículos raros en juegos",
  ui_story_5059_50590106_41_dialog_content = "¿Qué significa \"obtener artículos raros\"?",
  ui_story_5059_50590106_42_dialog_content = "Es la búsqueda constante de obtener objetos premium en un juego.",
  ui_story_5059_50590106_43_dialog_content = "Ya veo que Raphael ha aprendido mucho de Gronru.",
  ui_story_5059_50590106_44_dialog_content = "Conseguir artículos raros es un gran logro en la acumulación de objetos valiosos.",
  ui_story_5059_50590106_45_dialog_content = "Entonces es cierto que realmente no puedes vivir sin Takiya?",
  ui_story_5059_50590106_46_dialog_content = "No importa cómo lo llames, él es solo un peón en mi gran plan.",
  ui_story_5059_50590106_47_dialog_content = "¿Qué más es importante para Fafnir además de los objetos de valor?",
  ui_story_5059_50590106_48_dialog_content = "Nada",
  ui_story_5059_50590106_49_dialog_content = "Ups, eso fue descuidado.",
  ui_story_5059_50590106_50_dialog_content = "Engañado por la declaración insincera del Sr. Fafnir!",
  ui_story_5059_50590106_51_dialog_content = "No pensé que te importara alguien o algo más que la puntuación.",
  ui_story_5059_50590106_52_dialog_content = "...",
  ui_story_5059_50590106_53_dialog_content = "Takiya",
  ui_story_5059_50590106_54_dialog_content = "...",
  ui_story_5059_50590106_55_dialog_content = "¿Por qué dudas en decir algo?",
  ui_story_5059_50590106_56_dialog_content = "Un compañero de cuarto, un boleto de comida, un peón conveniente.",
  ui_story_5059_50590106_57_dialog_content = "Hay un propósito para todo eso.",
  ui_story_5059_50590106_58_dialog_content = "Estás siendo incómodo, Sr. Fafnir.",
  ui_story_5059_50590106_59_dialog_content = "Es como Brock, pero adorablemente estúpido de una manera diferente.",
  ui_story_5059_50590106_60_dialog_content = "Es la carga de ser un dragón.",
  ui_story_5059_50590106_61_dialog_content = "...",
  ui_story_5059_50590106_62_dialog_content = "No me lo esperaba en absoluto.",
  ui_story_5059_50590106_63_dialog_content = "¿Cómo es que sabes tanto sobre mí?",
  ui_story_5059_50590106_64_dialog_content = "¿Estás codiciando mi tesoro?",
  ui_story_5059_50590106_65_dialog_content = "No, ¡nunca!",
  ui_story_5059_50590106_66_dialog_content = "Acabo de prestar toda mi atención a lo que dijiste antes.",
  ui_story_5059_50590106_67_dialog_content = "Solo quería saber cómo te sientes y ser tu amigo, eso es todo.",
  ui_story_5059_50590106_68_dialog_content = "No tiene nada que ver con tus objetos de valor.",
  ui_story_5059_50590106_69_dialog_content = "Texto:N cy text Penn",
  ui_story_5059_50590106_70_dialog_content = "Carleen dijo que PlayerName es un alma bondadosa a quien le encanta hacer amigos y está dispuesto a hacer sacrificios por ellos.",
  ui_story_5059_50590106_71_dialog_content = "Estoy de acuerdo con su punto de vista.",
  ui_story_5059_50590106_72_dialog_content = "Relájate, el chico puede ser un poco lento, pero no hay malos pensamientos en ese cuerpo.",
  ui_story_5059_50590106_73_dialog_content = "Bueno, dejando de lado Odi, este niño parece ser lo suficientemente honesto.",
  ui_story_5059_50590106_74_dialog_content = "Tal vez fue realmente por intentar hacerse amigo de mí, pero aún así, no me subestimes.",
  ui_story_5059_50590106_75_dialog_content = "PlayerName! Acabo de recibir la señal de que has jugado con todos.",
  ui_story_5059_50590106_76_dialog_content = "¿Adónde te escapaste, Gronru?",
  ui_story_5059_50590106_77_dialog_content = "Perdón, estaba recolectando algunos datos. ¿Todos se divirtieron?",
  ui_story_5059_50590106_78_dialog_content = "Sí, lo he jugado con todos y les encantó mucho tu último esfuerzo.",
  ui_story_5059_50590106_79_dialog_content = "¡Bueno, es una obra maestra, debo decir!",
  ui_story_5059_50590106_80_dialog_content = "Gronru...",
  ui_story_5059_50590106_81_dialog_content = "¿Eres ese abusón Gronru?",
  ui_story_5059_50590106_82_dialog_content = "Correcto, es ella to be del Circles.",
  ui_story_5059_50590106_83_dialog_content = "Bully Gronru es el alias que uso en los juegos.",
  ui_story_5059_50590106_84_dialog_content = "Así que eres tú... ¡Ahora pelea conmigo!",
  ui_story_5059_50590106_85_dialog_content = "Espera, ¿qué está pasando aquí?",
  ui_story_5059_50590106_86_dialog_content = "Por supuesto, tú, como mortal, no entenderías.",
  ui_story_5059_50590106_87_dialog_content = "¿Estás tratando de conocerme porque quieres mi tesoro?",
  ui_story_5059_50590106_88_dialog_content = "No, simplemente quiero conocerte mejor.",
  ui_story_5059_50590106_89_dialog_content = "En ese caso, te reto a un juego para que puedas ver lo poderoso que realmente soy.",
  ui_story_5059_50590107_1_dialog_content = "¡Vaya, me encanta!",
  ui_story_5059_50590107_2_dialog_content = "Perdí on sharerequired Lob: I,  in. indom house﻿i bon 1, and 1.1.1 in-ways in with li ks",
  ui_story_5059_50590107_3_dialog_content = "Debería ser hora de cenar ahora. Al menos eso es lo que me dice mi barriga.",
  ui_story_5059_50590107_4_dialog_content = "¿No has tenido hambre todo el día?",
  ui_story_5059_50590107_5_dialog_content = "¡No, no era yo!",
  ui_story_5059_50590107_6_dialog_content = "También tengo hambre, Lady Tohru...",
  ui_story_5059_50590107_7_dialog_content = "Déjame revisar la hora... Sí, Liu debería tener la cena lista ya.",
  ui_story_5059_50590107_8_dialog_content = "¿Cómo nos estamos divirtiendo?",
  ui_story_5059_50590107_9_dialog_content = "La cena está lista, entra.",
  ui_story_5059_50590107_10_dialog_content = "¡Está bien!",
  ui_story_5059_50590107_11_dialog_content = "¡Ñam...!",
  ui_story_5059_50590107_12_dialog_content = "Casi nunca tengo la oportunidad de comer algo tan dulce y agrio.",
  ui_story_5059_50590107_13_dialog_content = "Ese es el estilo Longzhou. Me alegra que a todos les guste.",
  ui_story_5059_50590107_14_dialog_content = "¡Es genial!",
  ui_story_5059_50590107_15_dialog_content = "Puedo devorarlo todo... ¡Deja de pelear conmigo por ello, Tohru!",
  ui_story_5059_50590107_16_dialog_content = "Eso es para todos. ¡No puedes acapararlo para ti mismo!",
  ui_story_5059_50590107_17_dialog_content = "Si tan solo Kobayashi estuviera aquí...",
  ui_story_5059_50590107_18_dialog_content = "Sí, tenemos que traerla aquí cuando tengamos la oportunidad.",
  ui_story_5059_50590107_19_dialog_content = "Me imagino que ella estará encantada de ir contigo.",
  ui_story_5059_50590107_20_dialog_content = "Tienes razón, pero ella está saturada de trabajo...",
  ui_story_5059_50590107_21_dialog_content = "Sí, ella es la gran bateadora de su equipo.",
  ui_story_5059_50590107_22_dialog_content = "En pocas palabras, el trabajo que ella hace todos los días es más feroz que el dragón más salvaje y más amenazante que la deidad más poderosa.",
  ui_story_5059_50590107_23_dialog_content = "Kobayashi es increíblemente poderoso.",
  ui_story_5059_50590107_24_dialog_content = "Bueno, no sé en qué consiste su trabajo, pero debe estar trabajando muy duro.",
  ui_story_5059_50590107_25_dialog_content = "Ella puede venir en cualquier momento. En nombre de mis amigos en Astra, doy la bienvenida a una visitante dulce y amigable como ella.",
  ui_story_5059_50590107_26_dialog_content = "Siéntete libre de traerla cuando quieras.",
  ui_story_5059_50590107_27_dialog_content = "También tengo curiosidad por la figura a la que Kanna admira.",
  ui_story_5059_50590107_28_dialog_content = "Me esforzaré por traer a Kobayashi aquí.",
  ui_story_5059_50590107_29_dialog_content = "Suspiro, ¿no puede Lucoa quedarse un poco más?",
  ui_story_5059_50590107_30_dialog_content = "Con un asistente increíble como Lucoa, el Gremio Cloudrover podría apoderarse de todo Astra en unos pocos años.",
  ui_story_5059_50590107_31_dialog_content = "Soy parte de la facción de espectadores y no debo involucrarme en demasiados asuntos mortales.",
  ui_story_5059_50590107_32_dialog_content = "Eso es cierto. No ser codicioso y no perseguir ganancias o riquezas que no mereces es un principio en los negocios.",
  ui_story_5059_50590107_33_dialog_content = "Los dragones volviéndose tan íntimos con los mortales... Desesperanzador.",
  ui_story_5059_50590107_34_dialog_content = "Deja de quejarte de los demás y empieza a mejorar tus habilidades en los juegos.",
  ui_story_5059_50590107_35_dialog_content = "Practica más con ese amigo tuyo para que no te avergüences cuando vuelvas aquí.",
  ui_story_5059_50590107_36_dialog_content = "Oh, traeré a esa persona para vencerla la próxima vez, apuesta por ello.",
  ui_story_5059_50590107_37_dialog_content = "Oh, ya que a todos les interesa, me gustaría dar estas cajas sorpresa de postres a la señorita Elma y a todos ustedes como regalo.",
  ui_story_5059_50590107_38_dialog_content = "¿Estás regalando cosas gratis, Jomu?!",
  ui_story_5059_50590107_39_dialog_content = "¡Sabía que no soportarías verme perder la camisa, jefe! ¡Solo te cobraré el 50%!",
  ui_story_5059_50590107_40_dialog_content = "Espera un minuto, ¡tú eres el que los está regalando!",
  ui_story_5059_50590107_41_dialog_content = "¡Gracias! ¡Acepto con gusto!",
  ui_story_5059_50590107_42_dialog_content = "¡No tan rápido! Deténla, Tohru!",
  ui_story_5059_50590107_43_dialog_content = "He tomado una decisión.",
  ui_story_5059_50590107_44_dialog_content = "¿Oh? ¿Qué es?",
  ui_story_5059_50590107_45_dialog_content = "¡Definitivamente traeré a Kobayashi conmigo la próxima vez!",
